CREATE OR REPLACE PROCEDURE sp(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val integer := 0;
    status_text text := 'pending';
BEGIN
    IF arg1 < 0 THEN
        result_val := arg1 * -1;
        UPDATE chip_model SET RAM_MiB = result_val WHERE WiFi = arg2;
    ELSIF arg1 < 10 THEN
        result_val := arg1 + 5;
        DELETE FROM chip_model WHERE RAM_MiB = arg1;
    ELSIF arg1 < 20 THEN
        result_val := arg1 * 2;
        UPDATE screen_mode SET used_kb = arg3 + result_val WHERE Pixels = arg4;
    ELSIF arg1 < 30 THEN
        result_val := arg1 - 8;
        DELETE FROM screen_mode WHERE used_kb = arg3;
    ELSE
        result_val := arg1 / 2;
        status_text := 'processed';
    END IF;

    UPDATE phone
    SET Accreditation_level = Accreditation_level || '_screen_match'
    WHERE screen_mode IN (
        SELECT Graphics_mode::text
        FROM screen_mode
        WHERE Pixels = arg4 AND used_kb = arg3
    );

    UPDATE phone
    SET Accreditation_type = Accreditation_type || '_wifi_match'
    WHERE chip_model IN (
        SELECT Model_name
        FROM chip_model
        WHERE WiFi = arg2
    );

    UPDATE phone
    SET Hardware_Model_name = Hardware_Model_name || '_ram_wifi_match'
    WHERE chip_model IN (
        SELECT Model_name
        FROM chip_model
        WHERE RAM_MiB = arg1 AND WiFi = arg2
    );

    UPDATE phone
    SET Accreditation_type = Accreditation_type || '_dual_match'
    WHERE chip_model IN (
        SELECT Model_name
        FROM chip_model
        WHERE WiFi = arg2
    ) AND screen_mode IN (
        SELECT Graphics_mode::text
        FROM screen_mode
        WHERE Pixels = arg4
    );

    UPDATE chip_model
    SET WiFi = arg2 || status_text
    WHERE RAM_MiB = arg1;

    result_val := result_val + 3;

    UPDATE screen_mode
    SET Pixels = arg4 || '_updated'
    WHERE used_kb = arg3;

    DELETE FROM chip_model
    WHERE RAM_MiB > result_val;

    status_text := 'pending';

    UPDATE screen_mode
    SET used_kb = arg3 + 12
    WHERE Pixels = arg4;

    UPDATE chip_model
    SET RAM_MiB = result_val
    WHERE WiFi = arg2;

    result_val := result_val - 7;

    DELETE FROM screen_mode
    WHERE Pixels = arg4 || '_old';

    UPDATE chip_model
    SET WiFi = arg2 || '_updated'
    WHERE RAM_MiB = arg1;

    status_text := 'completed';

    UPDATE screen_mode
    SET used_kb = arg3 * 3
    WHERE Pixels = arg4;

    DELETE FROM chip_model
    WHERE WiFi = arg2 || status_text;

END;
$$;

